import { readFile, writeFile } from 'node:fs/promises'

// Bundle the official standalone runtime locally, so chart startup does not
// depend on a CDN or transmit credentials to a hosted terminal.
const root = new URL('../', import.meta.url)
const runtime = await readFile(new URL('node_modules/lightweight-charts/dist/lightweight-charts.standalone.production.js', root), 'utf8')
const license = await readFile(new URL('node_modules/lightweight-charts/LICENSE', root), 'utf8')
await writeFile(new URL('src/features/chart/tradingview-runtime.generated.ts', root),
  '// Generated by scripts/generate-tradingview-runtime.mjs; do not edit.\n' +
  `export const tradingViewRuntime = ${JSON.stringify(runtime)}\n` +
  `export const tradingViewLicense = ${JSON.stringify(license)}\n`)
console.log('Bundled the TradingView runtime and Apache license')
